import{_ as i,C as r,o as s,c,j as e,a as d,E as o,aj as l}from"./chunks/framework.m090XgxO.js";const x=JSON.parse('{"title":"Hotkeys","description":"","frontmatter":{},"headers":[],"relativePath":"components/hotkeys.md","filePath":"components/hotkeys.md","lastUpdated":1789206102000}'),h={name:"components/hotkeys.md"},b={id:"hotkeys",tabindex:"-1"};function u(p,t,k,y,m,f){const n=r("Badge"),a=r("XhDemo");return s(),c("div",null,[e("h1",b,[t[0]||(t[0]=d("Hotkeys ",-1)),o(n,{type:"info",text:"快捷键"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#hotkeys","aria-label":'Permalink to "Hotkeys <Badge type="info" text="快捷键" />"'},"​",-1))]),t[3]||(t[3]=l('<p>注册并匹配一组键盘组合，不渲染任何 DOM。可见键帽由<a href="./kbd">键帽</a>与<a href="./kbd-group">键帽组</a>负责，展示不会隐式安装全局监听。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/hotkeys" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/hotkeys" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/hotkeys" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/hotkeys.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一组组合的键帽：Mod 在 Mac 上出 ⌘、其余平台出 Ctrl，平台由组件自己测出来</p>',4)),o(a,{src:"hotkeys/01-basic"}),t[4]||(t[4]=e("h2",{id:"示例",tabindex:"-1"},[d("示例 "),e("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),t[5]||(t[5]=e("h3",{id:"限定范围",tabindex:"-1"},[d("限定范围 "),e("a",{class:"header-anchor",href:"#限定范围","aria-label":'Permalink to "限定范围"'},"​")],-1)),t[6]||(t[6]=e("p",null,"target 显式返回真实容器，只在这一层接组合",-1)),o(a,{src:"hotkeys/02-scoped"}),t[7]||(t[7]=e("h3",{id:"开关监听",tabindex:"-1"},[d("开关监听 "),e("a",{class:"header-anchor",href:"#开关监听","aria-label":'Permalink to "开关监听"'},"​")],-1)),t[8]||(t[8]=e("p",null,"enabled 只控制行为，KbdGroup 的 disabled 由业务显式同步",-1)),o(a,{src:"hotkeys/03-toggle"}),t[9]||(t[9]=e("h3",{id:"只注册不显示",tabindex:"-1"},[d("只注册不显示 "),e("a",{class:"header-anchor",href:"#只注册不显示","aria-label":'Permalink to "只注册不显示"'},"​")],-1)),t[10]||(t[10]=e("p",null,"useHotkeys 只安装监听，展示是 Kbd/KbdGroup 的独立职责",-1)),o(a,{src:"hotkeys/04-register-only"}),t[11]||(t[11]=l('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>给已有按钮、菜单项或命令增加键盘通路。</li><li>在组件生命周期内注册一条全局或明确局部范围的组合。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>只展示组合：用<a href="./kbd-group">键帽组</a>。</li><li>只展示一枚键：用<a href="./kbd">键帽</a>。</li><li>处理菜单、工具条等 APG 组件自身的方向键导航：使用对应组件内建行为。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>XhHotkeys</code> / <code>&lt;xh-hotkeys&gt;</code> 与 <code>useHotkeys</code> 都只安装监听，不输出键帽或展示容器。</li><li><code>keys</code> 必填、非空且必须恰好包含一枚主键；无效声明直接报错，不注册永远无法命中的死监听。</li><li><code>Mod</code> 在 Mac 上匹配 Meta，其余平台匹配 Control；平台自动侦测只在适配器挂载后发生。</li><li>修饰键逐个全等比对：注册 Ctrl+S 时，Ctrl+Shift+S 不会误命中。</li><li>命中后默认阻止浏览器默认动作，<code>preventDefault</code> 可显式关闭。</li><li>没有 Ctrl / Meta / Alt 的组合在输入框、文本域、下拉或可编辑区内让给输入。</li><li>输入法组合期间不响应。</li><li><code>target</code> 缺省为所属 Document；局部监听必须传返回真实 EventTarget 的 resolver，不猜组件父节点。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-hotkeys&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhHotkeys</code></td></tr><tr><td>组合式函数</td><td><code>useHotkeys</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr></tbody></table><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>boolean</code></td><td></td><td>监听是否生效，缺省开启；关掉后组合不再触发。</td></tr><tr><td><code>keys</code></td><td><code>string[]</code></td><td>是</td><td>组合里的各枚键，如 <code>[&#39;Mod&#39;, &#39;S&#39;]</code>。 &#39;Mod&#39; 在 Mac 上是 ⌘、其余平台是 Ctrl；&#39;Shift&#39; / &#39;Alt&#39; / &#39;Ctrl&#39; / &#39;Meta&#39; 各自对应那一枚。 除修饰键外必须且只能有一枚主键；空组合、空键或多主键声明直接报错。</td></tr><tr><td><code>onHotKey</code></td><td><code>(details: HotkeysTriggerDetails) =&gt; void</code></td><td></td><td>组合被按出来时的回调。</td></tr><tr><td><code>platform</code></td><td><code>HotkeysPlatform</code></td><td></td><td>按哪个平台解析匹配。 缺省 &#39;auto&#39;：读 navigator 会在服务端渲染时炸，所以 headless 只认显式值， 由适配器挂载后测出来传进来；未落定前按非 Mac 出。</td></tr><tr><td><code>preventDefault</code></td><td><code>boolean</code></td><td></td><td>命中后拦下浏览器的默认动作，缺省开启（注册 Mod+S 就是为了不让浏览器弹保存）。</td></tr><tr><td><code>target</code></td><td><code>HotkeysTarget</code></td><td></td><td>监听装在哪儿，缺省 &#39;document&#39;；局部监听传返回 EventTarget 的函数。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hot-key</code></td><td><code>HotkeysTriggerDetails</code></td><td>组合被按出来；detail 为 <code>{ keys: string[], event: KeyboardEvent }</code></td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useHotkeys</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>platform</code></td><td><code>HotkeysResolvedPlatform</code></td><td>实际采用的平台写法。</td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td>监听当前是否生效。</td></tr><tr><td><code>target</code></td><td><code>HotkeysTarget</code></td><td>监听该装在哪儿，适配器据此挑节点。</td></tr><tr><td><code>resolveTarget</code></td><td><code>(documentTarget: EventTarget | null) =&gt; EventTarget | null</code></td><td>解析并校验真实监听目标；适配器只负责提供所属 Document，不各自复制判断。</td></tr><tr><td><code>matches</code></td><td><code>(event: KeyboardEvent) =&gt; boolean</code></td><td>这次按键是否命中本组合（含输入法组合期与打字落点的排除）。</td></tr><tr><td><code>handleKeyDown</code></td><td><code>(event: KeyboardEvent) =&gt; void</code></td><td>适配器把它挂到监听节点的 keydown 上：命中即按 preventDefault 决定拦不拦，并回调 onHotKey。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/TR/uievents/#event-type-keydown" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>keys 指定的组合</code></td><td>enabled 未关，且不在输入法组合期</td><td>触发 onHotKey；preventDefault 开启（默认）时同时拦下浏览器的默认动作</td></tr><tr><td><code>keys 指定的组合</code></td><td>组合里没有 Ctrl / Meta / Alt，且按键落在输入框、文本域或可编辑区里</td><td>不触发也不拦：这类组合与打字撞车，输入优先</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><ul><li>快捷键不能成为动作的唯一路径，必须有可见且可点击的等价入口。</li><li>展示提示显式组合 KbdGroup；它用组级名称只朗读一次组合。</li><li>避免占用浏览器和读屏既有组合。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>XhHotkeys 负责触发动作，XhKbdGroup 负责在动作入口旁展示同一份 <code>keys</code>。</li><li>React/Vue 的 renderless 组件不渲染 children；Web Components 行为宿主也不接管子节点，保持元素为空。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>全局动作使用 <code>target=&quot;document&quot;</code> 缺省；局部动作显式返回面板节点。</li><li>组件卸载或组合式作用域销毁后监听会自动解绑；命令式提前停止使用 <code>stop()</code>。</li><li>跨平台主修饰键写 <code>Mod</code>，不要写死 Ctrl 或 Meta。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用 XhHotkeys 只为了显示键帽。</li><li>使用已删除的 <code>target=&quot;parent&quot;</code> 依赖不可见宿主猜测范围。</li><li>传空 keys 或多个主键，得到静默无效注册。</li></ul>',28))])}const P=i(h,[["render",u]]);export{x as __pageData,P as default};
